describe('Virtual Scroll List - 10,000 Rows Performance', () => {
  const TOTAL_ROWS = 10000;
  const VISIBLE_ROWS = 20;
  const ROW_HEIGHT = 40;
  const SCROLL_CONTAINER_HEIGHT = ROW_HEIGHT * VISIBLE_ROWS;

  beforeEach(() => {
    cy.visit('/virtual-scroll-list');
    cy.get('[data-testid="virtual-scroll-container"]').should('exist');
  });

  it('should render virtual scroll list with 10,000 rows without lag', () => {
    // Verify initial render performance
    cy.get('[data-testid="virtual-scroll-container"]')
      .should('have.css', 'height', `${SCROLL_CONTAINER_HEIGHT}px`);

    // Verify only visible rows are rendered in DOM
    cy.get('[data-testid="virtual-row"]').should('have.length.lessThan', VISIBLE_ROWS + 5);

    // Verify first row is visible
    cy.get('[data-testid="virtual-row"]').first().should('contain', 'Row 0');

    // Measure scroll performance
    cy.window().then((win) => {
      const startTime = performance.now();

      cy.get('[data-testid="virtual-scroll-container"]')
        .scrollTo(0, 5000, { duration: 1000 })
        .then(() => {
          const endTime = performance.now();
          const scrollDuration = endTime - startTime;

          // Assert scroll completes within acceptable time (< 2 seconds)
          expect(scrollDuration).to.be.lessThan(2000);
        });
    });

    // Verify rows update after scroll
    cy.get('[data-testid="virtual-row"]').first().should('not.contain', 'Row 0');
  });

  it('should handle rapid scrolling without memory leaks or lag', () => {
    const scrollContainer = cy.get('[data-testid="virtual-scroll-container"]');

    // Perform rapid scroll operations
    scrollContainer.scrollTo(0, 1000, { duration: 300 });
    scrollContainer.scrollTo(0, 3000, { duration: 300 });
    scrollContainer.scrollTo(0, 5000, { duration: 300 });
    scrollContainer.scrollTo(0, 2000, { duration: 300 });
    scrollContainer.scrollTo(0, 8000, { duration: 300 });

    // Verify DOM still contains only visible rows (no memory accumulation)
    cy.get('[data-testid="virtual-row"]').should('have.length.lessThan', VISIBLE_ROWS + 10);

    // Verify content is still accessible
    cy.get('[data-testid="virtual-row"]').first().should('be.visible');
  });

  it('should scroll to specific row and maintain performance', () => {
    const targetRow = 5000;
    const scrollPosition = targetRow * ROW_HEIGHT;

    cy.get('[data-testid="virtual-scroll-container"]')
      .scrollTo(0, scrollPosition, { duration: 500 });

    // Verify target row is visible
    cy.get('[data-testid="virtual-row"]')
      .filter((index, element) => {
        const rowNumber = parseInt(element.getAttribute('data-row-index'));
        return rowNumber >= targetRow - 5 && rowNumber <= targetRow + 5;
      })
      .should('have.length.greaterThan', 0);

    // Verify row count remains optimal
    cy.get('[data-testid="virtual-row"]').should('have.length.lessThan', VISIBLE_ROWS + 10);
  });

  it('should handle edge case - scroll to end of list', () => {
    const maxScrollPosition = (TOTAL_ROWS - VISIBLE_ROWS) * ROW_HEIGHT;

    cy.get('[data-testid="virtual-scroll-container"]')
      .scrollTo(0, maxScrollPosition, { duration: 500 });

    // Verify last rows are visible
    cy.get('[data-testid="virtual-row"]').last().should('contain', `Row ${TOTAL_ROWS - 1}`);

    // Verify no extra rows rendered beyond total
    cy.get('[data-testid="virtual-row"]').should('have.length.lessThan', VISIBLE_ROWS + 5);
  });

  it('should maintain scroll position after filtering', () => {
    const initialScrollPosition = 2000;

    cy.get('[data-testid="virtual-scroll-container"]')
      .scrollTo(0, initialScrollPosition, { duration: 300 });

    cy.get('[data-testid="filter-input"]').type('Row 50');
    cy.get('[data-testid="apply-filter-btn"]').click();

    // Verify filtered results are displayed
    cy.get('[data-testid="virtual-row"]').should('have.length.greaterThan', 0);

    // Verify performance is maintained with filtered data
    cy.get('[data-testid="virtual-row"]').should('have.length.lessThan', VISIBLE_ROWS + 10);
  });
});
